[SysAppField(fieldStr(FMCustomer, RecId), "RecId")]
public int64 recId(int64 _value=recIdInternal)
{
    recIdInternal = _value;
    return recIdInternal;
}

public static SysAppResponse deleteCustomer(SysAppEntityContext _entityContext, List _filterContextList)
{
    SysAppResponse response = new SysAppResponse();

    if (_entityContext.entityId())
    {
        int64 recIdPassed = str2Int64(_entityContext.entityId());
        FMCustomer customer;
        FMAddressTable address;

        ttsbegin;
        select * from customer
            where customer.RecId == recIdPassed;

        if (customer.RecId)
        {
            delete_from address
                where address.RecId == customer.AddressId;

            delete_from customer
                where Customer.RecId == recIdPassed;
        }
        ttscommit;

        response.addCommit(_entityContext);
    }

    return response;
}
